bool prepare_vm_display_frame_with_movie(
    VM& vm, const MoviePlayback* movie = nullptr) {
    bool cpu_windows_supported = true;
    for (const auto& [handle, window] : vm.window_objects()) {
        const uint32_t mode = vm.object_raw_field(handle, 0xB0U);
        // 0040C450 returns without writing for these two modes when the
        // transparency parameter is >= 256. This is a supported hidden
        // window, and must not force the legacy host renderer.
        if (window.visible &&
            vm.window_composite_alpha(handle) >= 0x100U &&
            mode != 1U && mode != 0x20U) {
            cpu_windows_supported = false;
            break;
        }
    }
    // DisplayBitmapDraw entries describe captures already executed by
    // draw_bitmap_to_display_objects; they are history, not pending draws.
    // The append-only icon layout history is diagnostic data as well. Live
    // processors own registered display objects; destruction unregisters them.
    // Retired layouts must neither force the legacy path nor draw ghost icons.
    const uint32_t unsupported =
        (movie != nullptr ? 1U : 0U) |
        (!vm.child_window_bitmap_commands().empty() ? 2U : 0U) |
        (!vm.direct_bitmap_draws().empty() ? 4U : 0U) |
        (!cpu_windows_supported ? 16U : 0U) |
        (!vm.window_objects().empty() &&
         vm.graphics_group_property_key() == 0 ? 32U : 0U);
    const auto trace_route = [&](bool ready) {
        if (!debug_trace(DebugTrace::Display)) return ready;
        static std::optional<uint32_t> previous;
        const uint32_t key = unsupported | (ready ? 0x100U : 0U);
        if (previous != key) {
            previous = key;
            std::cout << "DISPLAY_ROUTE tick=" << SDL_GetTicks()
                      << " ready=" << ready << " unsupported=0x" << std::hex
                      << unsupported << " ip=0x" << vm.main_thread().ip << std::dec
                      << " background=" << vm.background_type()
                      << " group=" << vm.graphics_group_property_key()
                      << " windows=" << vm.window_objects().size()
                      << " direct=" << vm.direct_bitmap_draws().size()
                      << " child=" << vm.child_window_bitmap_commands().size() << '\n';
        }
        return ready;
    };
    const bool cpu_scene_supported = unsupported == 0;
    if (cpu_scene_supported) {
        // Compose in engine canvas pixels. The client may be a smaller
        // presentation window (has_t:1280x720 for a1920x1080 canvas).
        // SDL applies that host scale only when presenting the primary.
        const auto [width, height] = vm.current_mode_dimensions();
        bool frame_ready = vm.has_display_frame(width, height);
        if (width != 0 && height != 0 &&
            (vm.display_dirty() || !frame_ready)) {
            const std::array<VM::DisplayDirtyRegion, 1> regions{{
                {{0, 0, static_cast<int32_t>(width) - 1,
                  static_cast<int32_t>(height) - 1},
                 0},
            }};
            frame_ready =
                vm.render_display_regions(width, height, regions);
        }
        return trace_route(width != 0 && height != 0 && frame_ready);
    }
    return trace_route(false);
}

